select event_id from intake_events where recorded_at >= '2026-09-08' order by recorded_at, seq limit 50;
select event_id from intake_events where system = 'codex' and recorded_at >= '2026-09-08' order by recorded_at, seq limit 50;
select event_id from intake_events where session_id = 'session-1' order by recorded_at, seq limit 50;
select event_id from intake_events where event_name = 'PreToolUse' order by recorded_at, seq limit 50;
select event_id from intake_events where tool_name = 'Shell' order by recorded_at, seq limit 50;
select receipt_id from intake_receipts where event_id = 'event-001' order by receipt_id;
select receipt_id from intake_receipts where received_at >= '2026-09-08' order by received_at, receipt_id;
select receipt_id from intake_deferred where state = 'pending' order by next_attempt_at, receipt_id limit 50;
select receipt_id from intake_deferred where event_id = 'event-001' and state = 'pending';
select evaluation_id from gate_evaluations where event_id = 'event-001';
select evaluation_id from gate_evaluations where receipt_id = 1 and mode = 'hot';
select evaluation_id from gate_evaluations where completed_at >= '2026-09-08' order by completed_at, evaluation_id limit 50;
select evaluation_id from gate_evaluations where final_verdict = 'allow' order by completed_at, evaluation_id limit 50;
select event_id from events where time >= '2026-09-08' order by time, event_id limit 50;
select event_id from events where system = 'codex' order by time, event_id limit 50;
select event_id from events where session_id = 'session-1' order by time, event_id limit 50;
select event_id from events where event_name = 'PreToolUse' order by time, event_id limit 50;
select event_id from events where tool_name = 'Shell' order by time, event_id limit 50;
select event_id from decisions where kind = 'allow';
select event_id from violations where rule = 'rule';
select layer_index from gate_evaluation_layers where evaluation_id = 'evaluation-event-001' order by layer_index;
select namespace from gate_evaluation_labels where evaluation_id = 'evaluation-event-001' order by namespace, label_version;
